# -- 会话快照与公钥解析（轮换后收集/就绪会话改用当前在用份额）------------

def _session_snapshot(self, wallet_id: str, record: dict) -> dict:
    """解析会话当前有效快照 {"share_ids": [...], "public": {sid: hex}}。

    - signed/expired 为终态：冻结创建时快照（signed 重放旧份额仍需其
      公钥；expired 不再接受投递）；
    - collecting/ready：若记录快照仍是钱包当前在用份额则沿用；一旦
      轮换激活（当前份额不同于快照），改用钱包当前两份在用份额。
      后续再轮换同样跟踪到最新在用份额。
    调用方须持钱包事务锁。"""
    current = self._store.get_wallet(wallet_id)
    if current is None or not isinstance(current.get("shares"), list):
        raise RecoveryError(
            f"wallet {wallet_id!r} metadata missing during session "
            "snapshot resolution"
        )
    current_ids = [s["share_id"] for s in current["shares"]]
    if record["state"] in ("signed", "expired") or current_ids == list(
        record["share_ids"]
    ):
        ids = list(record["share_ids"])
    else:
        ids = current_ids
    public = self._session_share_public_keys(wallet_id, ids, current)
    return {"share_ids": ids, "public": public}

def _session_share_public_keys(
    self, wallet_id: str, share_ids: list[str], current_meta: dict
) -> dict[str, str]:
    """收集给定份额 id 对应的份额公钥。

    当前在用份额取自钱包元数据；已轮换失效的旧份额公钥只能从轮换
    激活记录的备份链（previous_public_key 为旧钱包公钥）获取，确保
    signed 会话旧份额同值重放与启动恢复的逐份重验有权威公钥可用，
    而不是信任请求自报或猜写。任一份额找不到权威公钥即 fail-closed。
    """
    public: dict[str, str] = {}
    for entry in current_meta.get("shares", []):
        if (
            isinstance(entry, dict)
            and isinstance(entry.get("share_id"), str)
            and isinstance(entry.get("public_key"), str)
        ):
            public[entry["share_id"]] = entry["public_key"]
    if all(sid in public for sid in share_ids):
        return {sid: public[sid] for sid in share_ids}
    # 沿轮换激活记录回溯旧公钥（每个 active 记录携带 previous_public_key
    # 与该轮换的 share_ids；旧钱包公钥两半即旧两份份额公钥）。
    known = set(public)
    missing = [sid for sid in share_ids if sid not in known]
    for rotation in self._store.list_rotations(wallet_id):
        if rotation.get("state") != "active":
            continue
        rids = rotation.get("share_ids")
        previous_hex = rotation.get("previous_public_key")
        if (
            not isinstance(rids, list)
            or not isinstance(previous_hex, str)
        ):
            continue
        try:
            previous = bytes.fromhex(previous_hex)
        except ValueError:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rotation.get('rotation_id')!r} "
                "has a non-hex previous_public_key"
            )
        if len(previous) != 64:
            raise RecoveryError(
                f"wallet {wallet_id!r} rotation {rotation.get('rotation_id')!r} "
                "has a bad-length previous_public_key"
            )
        # 该轮换激活前的两份旧份额：顺序无法仅凭旧公钥确定，但旧
        # share-1/share-2 或 <rid>-share-N 的两半顺序约定固定为
        # 该旧公钥的前 32/后 32 字节；结合轮换记录链中的 share_ids
        # 顺序（share-N 后缀决定先后）映射。
        old_ids = [
            sid for sid in missing
            if sid not in rids and sid not in known
        ]
        ordered = self._ordered_previous_share_ids(
            wallet_id, rotation, old_ids, known
        )
        half_for = {ordered[0]: previous[:32].hex()}
        half_for[ordered[1]] = previous[32:].hex()
        for sid in old_ids:
            if sid in half_for:
                public[sid] = half_for[sid]
                known.add(sid)
    absent = [sid for sid in share_ids if sid not in public]
    if absent:
        raise RecoveryError(
            f"wallet {wallet_id!r} sign session references shares "
            f"{absent!r} with no resolvable public key"
        )
    return {sid: public[sid] for sid in share_ids}

def _ordered_previous_share_ids(
    self,
    wallet_id: str,
    rotation: dict,
    candidate_ids: list[str],
    known: set[str],
) -> list[str]:
    """给定一次轮换与待解析的旧份额 id，确定其"第一份/第二份"顺序。

    新轮换份额 id 形如 ``<rotation_id>-share-1/2``；轮换前的旧份额
    对要么是固定 ``share-1/share-2``，要么是更早轮换的
    ``<rid>-share-1/2``。同一钱包历史上任意时刻恰有两份份额，因此
    候选旧 id 中以 ``-share-1`` 结尾者为第一份、``-share-2`` 结尾者
    为第二份；无法据此判定（被外部改成任意 id）时 fail-closed。
    """
    ordered: list[str] = []
    for suffix in ("-share-1", "-share-2"):
        matches = [sid for sid in candidate_ids if sid.endswith(suffix)]
        if len(matches) != 1:
            raise RecoveryError(
                f"wallet {wallet_id!r} cannot order previous share ids "
                f"{candidate_ids!r} for rotation "
                f"{rotation.get('rotation_id')!r}"
            )
        ordered.append(matches[0])
    return ordered

@staticmethod
def _session_expires_at(record: dict):
    return parse_utc_iso(record["expires_at"])

def _session_expire_if_needed(
    self, wallet_id: str, record: dict
) -> dict:
    """懒过期：collecting 与 ready 会话都受 expires_at 约束。

    到点则原子持久化为 expired 并只记一次 action=expired 的
    session_event；投递路径随后返回 409，终态不再聚合。signed/expired
    不再受到期时间影响。调用方须持钱包事务锁。"""
    if record["state"] not in ("collecting", "ready"):
        return record
    expires_at = self._session_expires_at(record)
    if expires_at is None or datetime.now(timezone.utc) < expires_at:
        return record
    expired = dict(record)
    expired["state"] = "expired"
    expired.pop("aggregate_signature", None)
    self._store.update_sign_session(wallet_id, record["id"], expired)
    try:
        self._emit(
            wallet_id,
            self._audit_event(
                audit.TYPE_SESSION_EVENT,
                request_id=record["id"],
                details={"action": "expired", "state": "expired"},
            ),
        )
    except BaseException:
        # 状态/事件原子：事件未落盘恢复原状态
        self._store.update_sign_session(wallet_id, record["id"], record)
        raise
    return expired

