    只按当前快照计数，轮换前收到的旧份额已剔除、不计入 received。"""
    effective = snapshot if snapshot is not None else record
    current_ids = list(effective["share_ids"])
    received_set = {
        entry["share_id"] for entry in record["shares"]
    }
    received = [sid for sid in current_ids if sid in received_set]
    missing = [sid for sid in current_ids if sid not in received_set]
    view = {
        "id": record["id"],
        "message": record["message"],
        "state": record["state"],
        "received_shares": received,
